# Rebuild the original diagnostic/surface arrangements from saved numerical data.
source('scripts/revision/common.R')
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(sf);library(jsonlite)})
directory <- file.path(output_dir,'figure_revision_original_design','supplement_S11_S12')
dir.create(directory,recursive=TRUE,showWarnings=FALSE)
skill <- Sys.getenv("AMMO_FIGURE_QA_DIR", unset="")
source(file.path(skill,'scripts/panel_alignment.R'));source('scripts/revision/measure_panels.R')
python <- Sys.getenv("AMMO_PYTHON", unset="python3")
theme_set(theme_classic(base_size=9)+theme(axis.text=element_text(size=8,colour='black'),axis.title=element_text(size=8),legend.text=element_text(size=8),legend.title=element_text(size=8),plot.tag=element_text(size=12),plot.margin=margin(5,6,5,6)))
exports <- character()
export <- function(p,name,width,height,caption,alignment=FALSE){
 stem<-file.path(directory,name)
 if(alignment)require_patchwork_panel_alignment(p,paste0(stem,'.alignment-layout.json'),paste0(stem,'.alignment.json'),width/25.4,height/25.4,audit_script=file.path(skill,'scripts/audit_panel_alignment.py'),python=python)
 pdf(paste0(stem,'.pdf'),width=width/25.4,height=height/25.4,useDingbats=FALSE);print(p);dev.off()
 ggsave(paste0(stem,'.png'),p,width=width,height=height,units='mm',dpi=600,type='cairo',bg='white');saveRDS(p,paste0(stem,'.rds'))
 writeLines(caption,paste0(stem,'.caption.txt'))
 stopifnot(system2(python,c(shQuote(file.path(skill,'scripts/audit_pdf_text.py')),shQuote(paste0(stem,'.pdf')),'--min-pt','8','--json'),stdout=paste0(stem,'.text-audit.json'))==0)
 stopifnot(system2(python,c(shQuote(file.path(skill,'scripts/audit_figure_collisions.py')),shQuote(paste0(stem,'.pdf')),'--json-out',shQuote(paste0(stem,'.collision-audit.json'))))==0)
 exports<<-c(exports,paste0(stem,'.pdf'))
}
input <- file.path(output_dir,'sdm_reconstruction')
roc<-read.csv(file.path(input,'cross_validation_ROC.csv'));cv<-read.csv(file.path(input,'cross_validation.csv'))
grid<-seq(0,1,length.out=201)
curves<-vapply(split(roc,roc$fold),function(d)approx(d$FPR,d$TPR,xout=grid,ties=max,rule=2)$y,numeric(length(grid)))
roc_summary<-data.frame(FPR=grid,TPR=rowMeans(curves),SD=apply(curves,1,sd));write_csv(roc_summary,file.path(directory,'S11_ROC_display_source.csv'))
a<-ggplot(roc_summary,aes(FPR,TPR))+geom_ribbon(aes(ymin=pmax(0,TPR-SD),ymax=pmin(1,TPR+SD)),fill='blue',alpha=.35)+geom_line(colour='red',linewidth=.45)+geom_abline(intercept=0,slope=1,linewidth=.25)+coord_equal()+scale_x_continuous(limits=c(0,1),breaks=c(0,.5,1))+scale_y_continuous(limits=c(0,1),breaks=c(0,.5,1))+labs(x='False positive rate',y='True positive rate',tag='a')
results<-read.csv(file.path(input,'maxent_final_results_long.csv'))
jack<-read.csv(file.path(output_dir,'figures/sdm_reconstruction/jackknife_source.csv'))
full_gain<-results$value[results$metric=='Regularized.training.gain'];stopifnot(length(full_gain)==1)
jack<-rbind(jack,data.frame(predictor=c(toupper(bio_names),'Elevation'),type='All predictors',gain=full_gain))
jack$predictor<-factor(jack$predictor,levels=rev(c('Elevation','BIO4','BIO5','BIO6','BIO15','BIO17')))
jack$type<-factor(jack$type,levels=c('Without predictor','Predictor only','All predictors'))
write_csv(jack,file.path(directory,'S11_jackknife_display_source.csv'))
b<-ggplot(jack,aes(gain,predictor,fill=type))+geom_col(position=position_dodge(width=.75),width=.7)+scale_fill_manual(values=c('Without predictor'='cyan','Predictor only'='blue','All predictors'='red'))+labs(x='Regularized training gain',y=NULL,tag='b',fill=NULL)+theme(legend.position='bottom',legend.text=element_text(size=8),legend.key.size=grid::unit(2,'mm'))+guides(fill=guide_legend(ncol=1))
responses<-read.csv(file.path(input,'conditional_response_curves.csv'))
variables<-c('elevation','bio4','bio5','bio6','bio15','bio17')
labels<-c(elevation='Elevation (m)',bio4='BIO4 (SD ×100)',bio5='BIO5 (°C)',bio6='BIO6 (°C)',bio15='BIO15 (CV)',bio17='BIO17 (mm)')
small<-lapply(seq_along(variables),function(i){v<-variables[i];ggplot(responses[responses$predictor==v,],aes(value,suitability))+geom_line(colour='red',linewidth=.45)+scale_y_continuous(limits=c(0,1),breaks=c(0,.5,1))+scale_x_continuous(breaks=scales::breaks_pretty(n=2))+labs(x=labels[[v]],y=if(i%%2==1)'Suitability'else NULL,tag=if(i==1)'c'else NULL)})
# Explicit original asymmetry: a/b left; six curves in 3×2 right.
parts<-c(list(a,b),small)
design<-c(area(1,1,3,2),area(4,1,6,2),area(1,3,2,3),area(1,4,2,4),area(3,3,4,3),area(3,4,4,4),area(5,3,6,3),area(5,4,6,4))
fig<-wrap_plots(parts,design=design)
write_json(list(validated=TRUE,layout='Original asymmetric diagnostic layout; a/b occupy left half, six c-curves in right half',comparison_policy='Do not compare unequal original ROC/jackknife panels as equal-sized grid panels',width_mm=190,height_mm=175),file.path(directory,'S11_layout_contract.json'),pretty=TRUE,auto_unbox=TRUE)
export(fig,'Figure_S11',190,175,c('Figure S11. Diagnostics of the reconstructed MaxEnt model. (a) Mean held-out ROC across ten random folds; blue band is ±1SD among folds after interpolation onto a common false-positive-rate grid, not a confidence interval. (b) Regularized training gain with each predictor omitted, each predictor alone, and all predictors. (c) Saved final-model conditional response curves, with other variables held at mean occurrence values; no response-curve uncertainty was available. BIO4: temperature seasonality; BIO5: maximum temperature of the warmest month; BIO6: minimum temperature of the coldest month; BIO15: precipitation seasonality; BIO17: precipitation of the driest quarter. ROC discrimination compares presences with background cells and does not establish spatial transferability. All curves and gains are from saved results, without model refitting.'),FALSE)
# Original two-panel EEMS q/m design and orange-white-cyan diverging scale.
q<-read.csv(file.path(output_dir,'eems_existing_audit/xyq.values.csv'));m<-read.csv(file.path(output_dir,'eems_existing_audit/xym.values.csv'))
outer<-as.matrix(read.table(file.path(bundle,'eems/ammo_all.outer')));if(!all(outer[1,]==outer[nrow(outer),]))outer<-rbind(outer,outer[1,])
coords<-read.table(file.path(bundle,'eems/ammo_all.coord'),col.names=c('x','y'))
poly<-st_sfc(st_polygon(list(outer)),crs=4326)
inside<-lengths(st_intersects(st_as_sf(q,coords=c('x','y'),crs=4326),poly))>0
q$q[!inside]<-NA_real_;m$m[!inside]<-NA_real_
one<-function(d,var,tag,lim,breaks){names(d)[3]<-'value';ggplot(d,aes(x,y))+geom_raster(aes(fill=value),interpolate=FALSE)+geom_path(data=as.data.frame(outer),aes(V1,V2),inherit.aes=FALSE,linewidth=.25,colour='grey40')+geom_point(data=coords,size=.55,colour='black')+scale_fill_gradientn(colours=c('#D95F02','#FFFFFF','#00BFC4'),values=c(0,.5,1),limits=c(-lim,lim),breaks=breaks,na.value='white',name=paste0('log10 ',var))+coord_fixed(ratio=1/cos(mean(q$y)*pi/180),xlim=range(outer[,1]),ylim=range(outer[,2]),expand=FALSE)+scale_x_continuous(breaks=c(102,106,110))+scale_y_continuous(breaks=c(37,40,43))+labs(x='Longitude (°E)',y='Latitude (°N)',tag=tag)+theme(legend.position='right',panel.grid=element_blank(),legend.key.height=unit(6,'mm'))}
fig<-one(q,'q','a',.11,c(-.1,0,.1))+one(m,'m','b',2.1,c(-2,0,2))+plot_layout(nrow=1)
export(fig,'Figure_S12',190,90,c('Figure S12. Archived EEMS surfaces. (a) Relative effective diversity q and (b) relative effective migration m, both on a log10 scale. Black points denote the217 sampling locations. Orange indicates lower and cyan higher relative values. Surfaces retain the archived700-deme, seed123 run with2million iterations,1million burn-in and100 retained draws; no new MCMC was run. These model components do not measure migrants per generation, contemporary connectivity or observed heterozygosity. Independent-chain convergence was not established.'),TRUE)
save_session(directory);marker(directory,list(scope='Original S11/S12 arrangements redrawn from saved numerical data',PDFs=exports,PNG=sub('pdf$','png',exports),no_model_refitting=TRUE,no_MCMC=TRUE,manual_visual_QA='Pending'))
